  const products = await getProducts()

  async function syncCatalog() {
    'use server'

    // Simulate syncing with external ERP/PIM system
    // In production, this would make actual API calls to external systems
    await new Promise(resolve => setTimeout(resolve, 50))

    // Mark the products cache as stale
    // Using 'max' profile for stale-while-revalidate semantics
    // This allows users to continue working with stale data while
    // fresh data is fetched in the background on next access
    revalidateTag('products', 'max')
  }

  return (
    <div style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
